}

:root {
    --bg-primary: #0f0f0f;
    --bg-secondary: #1a1a1a;
    --bg-tertiary: #2a2a2a;
    --text-primary: #e0e0e0;
    --text-secondary: #a0a0a0;
    --border-color: #3a3a3a;
    --accent-color: #4a9eff;
    --accent-hover: #3583cc;
    --error-color: #ff6b6b;
    --error-bg: #3a1a1a;
    --success-color: #51cf66;
    --success-bg: #1a3a1a;
    --transition: all 0.3s ease;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
        'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.container {
    width: 100%;
    max-width: 500px;
    background-color: var(--bg-secondary);
    border-radius: 12px;
    border: 1px solid var(--border-color);
    padding: 40px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
}

header {
    margin-bottom: 30px;
    text-align: center;
}

header h1 {
    font-size: 28px;
    font-weight: 700;
    margin-bottom: 8px;
    color: var(--text-primary);
}

header p {
    font-size: 14px;
    color: var(--text-secondary);
}

main {
    width: 100%;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.form-field label {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-primary);
    display: block;
    margin-bottom: 2px;
}

.form-field input {
    padding: 12px 14px;
    font-size: 14px;
    background-color: var(--bg-tertiary);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    transition: var(--transition);
    font-family: inherit;
}

.form-field input::placeholder {
    color: var(--text-secondary);
}

.form-field input:focus {
    outline: none;
    border-color: var(--accent-color);
    box-shadow: 0 0 0 3px rgba(74, 158, 255, 0.1);
    background-color: rgba(74, 158, 255, 0.03);
}

.form-field input:invalid:not(:placeholder-shown) {
    border-color: var(--error-color);
    background-color: var(--error-bg);
}

.form-field input:valid:not(:placeholder-shown):not([type="email"]),
.form-field input:valid:not(:placeholder-shown)[type="email"] {
    border-color: var(--success-color);
}

.helper-text {
    font-size: 12px;
    color: var(--text-secondary);
    margin-top: 2px;
}

.validation-message {
    font-size: 12px;
    color: var(--error-color);
    min-height: 16px;
    display: block;
    margin-top: 2px;
}

.validation-message.show {
    animation: slideDown 0.2s ease;
}

@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-4px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.success-message {
    font-size: 14px;
    color: var(--success-color);
    background-color: var(--success-bg);
    border: 1px solid var(--success-color);
    border-radius: 6px;
    padding: 12px 14px;
    margin-top: 20px;
    min-height: 0;
    opacity: 0;
    visibility: hidden;
    transition: var(--transition);
}

.success-message.show {
    opacity: 1;
    visibility: visible;
    animation: slideDown 0.3s ease;
}

.submit-button {
    padding: 12px 24px;
    font-size: 14px;
    font-weight: 600;
    background-color: var(--accent-color);
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: var(--transition);
    font-family: inherit;
    margin-top: 8px;
}

.submit-button:hover:not(:disabled) {
    background-color: var(--accent-hover);
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(74, 158, 255, 0.3);
}

.submit-button:active:not(:disabled) {
    transform: translateY(0);
    box-shadow: 0 2px 6px rgba(74, 158, 255, 0.3);
}

.submit-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.submit-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(74, 158, 255, 0.3);
}

@media (max-width: 480px) {
    .container {
        padding: 24px;
    }

    header h1 {
        font-size: 24px;
    }

    .contact-form {
        gap: 20px;
    }
}
