class ContactFormController {
    constructor(formId) {
        this.form = document.getElementById(formId);
        this.fields = {
            fullName: document.getElementById('fullName'),
            email: document.getElementById('email'),
            phone: document.getElementById('phone')
        };
        this.errors = {
            fullName: document.getElementById('fullNameError'),
            email: document.getElementById('emailError'),
            phone: document.getElementById('phoneError')
        };
        this.successMessage = document.getElementById('successMessage');
        this.init();
    }

    init() {
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        Object.keys(this.fields).forEach(fieldName => {
            this.fields[fieldName].addEventListener('blur', () => this.validateField(fieldName));
            this.fields[fieldName].addEventListener('input', () => this.validateField(fieldName));
        });
    }

    validateField(fieldName) {
        const field = this.fields[fieldName];
        const errorElement = this.errors[fieldName];
        let isValid = true;
        let errorMessage = '';

        if (fieldName === 'fullName') {
            if (!field.value.trim()) {
                isValid = false;
                errorMessage = 'Full name is required';
            } else if (field.value.trim().length < 2) {
                isValid = false;
                errorMessage = 'Full name must be at least 2 characters';
            }
        } else if (fieldName === 'email') {
            if (!field.value.trim()) {
                isValid = false;
                errorMessage = 'Email address is required';
            } else if (!this.isValidEmail(field.value)) {
                isValid = false;
                errorMessage = 'Please enter a valid email address';
            }
        } else if (fieldName === 'phone') {
            if (field.value.trim() && !this.isValidPhone(field.value)) {
                isValid = false;
                errorMessage = 'Please enter a valid phone number';
            }
        }

        if (!isValid) {
            errorElement.textContent = errorMessage;
            errorElement.classList.add('show');
            field.setAttribute('aria-invalid', 'true');
        } else {
            errorElement.textContent = '';
            errorElement.classList.remove('show');
            field.setAttribute('aria-invalid', 'false');
        }

        return isValid;
    }

    isValidEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }

    isValidPhone(phone) {
        // Accepts formats: (123) 456-7890, 123-456-7890, 1234567890, or variations
        const phoneRegex = /^[\d\s\-()]{10,}$|^[\d]{10}$/;
        const digitsOnly = phone.replace(/\D/g, '');
        return phoneRegex.test(phone) && digitsOnly.length >= 10;
    }

    isFormValid() {
        let isValid = true;

        // Validate required fields
        if (!this.fields.fullName.value.trim()) {
            isValid = false;
            this.validateField('fullName');
        }

        if (!this.fields.email.value.trim()) {
            isValid = false;
            this.validateField('email');
        }

        // Validate optional phone if provided
        if (this.fields.phone.value.trim()) {
            if (!this.isValidPhone(this.fields.phone.value)) {
                isValid = false;
                this.validateField('phone');
            }
        }

        // Also validate format for required fields
        if (this.fields.fullName.value.trim() && this.fields.fullName.value.trim().length < 2) {
            isValid = false;
            this.validateField('fullName');
        }

        if (this.fields.email.value.trim() && !this.isValidEmail(this.fields.email.value)) {
            isValid = false;
            this.validateField('email');
        }

        return isValid;
    }

    handleSubmit(e) {
        e.preventDefault();

        if (!this.isFormValid()) {
            return;
        }

        // Simulate form submission
        const submitButton = this.form.querySelector('.submit-button');
        submitButton.disabled = true;
        submitButton.textContent = 'Sending...';

        setTimeout(() => {
            const formData = {
                fullName: this.fields.fullName.value.trim(),
                email: this.fields.email.value.trim(),
                phone: this.fields.phone.value.trim()
            };

            console.log('Form submitted:', formData);

            // Show success message
            this.successMessage.textContent = 'Thank you! Your message has been sent successfully.';
            this.successMessage.classList.add('show');

            // Reset form
            this.form.reset();
            Object.keys(this.errors).forEach(fieldName => {
                this.errors[fieldName].textContent = '';
                this.errors[fieldName].classList.remove('show');
                this.fields[fieldName].setAttribute('aria-invalid', 'false');
            });

            // Reset button
            submitButton.disabled = false;
            submitButton.textContent = 'Send Message';

            // Hide success message after 5 seconds
            setTimeout(() => {
                this.successMessage.classList.remove('show');
            }, 5000);
        }, 800);
    }
}

// Initialize the form when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new ContactFormController('contactForm');
});

